<script setup>
import {computed,defineAsyncComponent,onBeforeUnmount,onMounted,ref} from 'vue'
import {api,waitJob} from '../api'
import JobProgress from './JobProgress.vue'
const Generate=defineAsyncComponent(()=>import('../views/Generate.vue'))
const ImageComparison=defineAsyncComponent(()=>import('./ImageComparison.vue'))
const props=defineProps({profile:Object}),emit=defineEmits(['changed'])
const section=ref('manual'),caps=ref({items:[],local:[]}),providers=ref([]),batches=ref({items:[],total:0}),offset=ref(0),busy=ref(false),error=ref(''),job=ref(null),file=ref(null),parameters=ref('{}'),design=ref(''),cross=ref(false),left=ref(''),right=ref(''),comparison=ref(null),recipe=ref(null),recipeKey=ref(0)
const contract=ref({provider_id:'',name:'',model:'',confirmed_images_api:false,legacy_b64:false}),form=ref({service_id:'',positive:'',size:'1024x1024',count:1})
const lifecycle=new AbortController();onBeforeUnmount(()=>lifecycle.abort())
const images=computed(()=>props.profile.references.filter(r=>r.kind==='asset'&&r.is_image&&r.status==='ok'))
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(!lifecycle.signal.aborted)error.value=e.message}finally{if(!lifecycle.signal.aborted)busy.value=false}}
async function load(){[caps.value,batches.value]=await Promise.all([api.get('/api/oc-image-services'),api.get(`/api/oc/${props.profile.id}/batches`,{offset:offset.value})])}
onMounted(()=>run(load))
async function manual(){if(!file.value)return;const data=new FormData();data.append('file',file.value);data.append('expected_version',props.profile.version);data.append('parameters',parameters.value);data.append('allow_cross_world',cross.value);if(design.value)data.append('design_id',design.value);await api.upload(`/api/oc/${props.profile.id}/manual-image`,data);file.value=null;emit('changed');await load()}
async function apiRun(){job.value=await api.post(`/api/oc/${props.profile.id}/generate-api`,{...form.value,service_id:Number(form.value.service_id),expected_version:props.profile.version,design_id:design.value||null});await waitJob(job.value.id,j=>job.value=j,700,lifecycle.signal);if(lifecycle.signal.aborted)return;emit('changed');await load()}
async function openApi(){section.value='api';providers.value=(await api.get('/api/ai/providers')).items}
async function register(){await api.post('/api/oc-image-services',{...contract.value,provider_id:Number(contract.value.provider_id)});await load()}
async function compare(){comparison.value=await api.get(`/api/oc/${props.profile.id}/compare`,{left:left.value,right:right.value})}
function retry(row){if(row.recipe.backend==='images-api'){section.value='api';form.value={service_id:row.recipe.service_id,positive:row.recipe.positive,size:row.recipe.size,count:row.recipe.count};design.value=row.recipe.design_id||''}else{section.value='local';recipe.value=row.recipe;recipeKey.value++}}
async function generated(){emit('changed');await run(load)}
const media=rid=>`/api/oc/${props.profile.id}/images/${rid}/file`
</script>
<template><div class="grid">
<p v-if="error" class="notice" role="alert">{{error}}</p><nav class="row"><button @click="section='manual'">手动图片</button><button @click="section='local'">WebUI / Forge / ComfyUI</button><button @click="run(openApi)">图像API</button><button @click="section='compare'">图片对比</button></nav>
<section v-if="section==='manual'" class="card grid"><h2>手动图片与参数</h2><p class="muted small">不需要GPU或AI服务。图片复用素材库内容去重；已有不同归属时需要明确允许引用。</p><label class="field">选择图片<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" @change="file=$event.target.files[0]"/></label><label class="field">关联造型<select v-model="design"><option value="">默认方案</option><option v-for="d in profile.designs" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label class="field">可选生成参数（JSON对象）<textarea v-model="parameters" placeholder='{"model":"模型名","seed":42,"loras":[]}'/></label><label class="row"><input v-model="cross" type="checkbox"/>明确允许与不同世界观已存在图片关联</label><button :disabled="busy||!file" @click="run(manual)">上传并关联图片</button><small>绘画工程可在素材关联页直接引用PSD、CLIP、KRA等，保持原件。</small></section>
<Generate v-else-if="section==='local'" :key="recipeKey" :oc-profile="profile" :initial-recipe="recipe" @generated="generated"/>
<section v-else-if="section==='api'" class="card grid"><h2>明确支持图像生成的API</h2><p class="notice">已配置聊天模型不会自动出现在这里。仅支持 Images API 的正向提示词与尺寸；Checkpoint、LoRA、反向提示词、种子、CFG及采样器不传给此适配器。具体尺寸由服务决定。点击生成会向所选服务发送提示词并可能计费。</p><label class="field">图像服务<select v-model="form.service_id"><option value="">先明确登记服务能力</option><option v-for="s in caps.items" :key="s.id" :value="s.id">{{s.name}} · {{s.model}} · {{s.last_success?'曾成功返回图像':'尚未验证'}}</option></select></label><label class="field">正向提示词<textarea v-model="form.positive"/></label><div class="grid cols-2"><label class="field">API图像尺寸<input v-model="form.size" placeholder="1024x1024"/></label><label class="field">生成张数<input v-model.number="form.count" type="number" min="1" max="8"/></label><label class="field">关联造型<select v-model="design"><option value="">默认方案</option><option v-for="d in profile.designs" :key="d.id" :value="d.id">{{d.name}}</option></select></label></div><button class="primary" :disabled="busy||!form.service_id||!form.positive.trim()" @click="run(apiRun)">向所选图像服务生成</button><JobProgress :job="job"/>
<details><summary>登记图像接口能力</summary><div class="grid"><label class="field">复用已配置的Provider凭据<select v-model="contract.provider_id"><option value="">请在设置页配置Provider</option><option v-for="p in providers" :key="p.id" :value="p.id">{{p.name}} · #{{p.id}}</option></select></label><label class="field">服务名称<input v-model="contract.name"/></label><label class="field">图像模型ID<input v-model="contract.model"/></label><label class="row"><input v-model="contract.legacy_b64" type="checkbox"/>旧式接口需要 response_format=b64_json</label><label class="row"><input v-model="contract.confirmed_images_api" type="checkbox"/>已核对服务文档，确认支持 /images/generations 和该图像模型</label><button :disabled="busy||!contract.provider_id||!contract.confirmed_images_api||!contract.name||!contract.model" @click="run(register)">保存能力声明（不调用服务）</button><RouterLink to="/settings">管理Provider</RouterLink><small>新式图像模型返回base64时无需response_format；URL返回适配尚未支持。能力声明不是成功连接测试。</small></div></details></section>
<section v-else-if="section==='compare'" class="card grid"><h2>同一OC的图片与参数比较</h2><div class="grid cols-2"><label class="field">左图片<select v-model="left"><option value="">选择图片</option><option v-for="r in images" :key="r.id" :value="r.id">{{r.title}} · {{r.role}} · {{r.id.slice(0,6)}}</option></select></label><label class="field">右图片<select v-model="right"><option value="">选择图片</option><option v-for="r in images" :key="r.id" :value="r.id">{{r.title}} · {{r.role}} · {{r.id.slice(0,6)}}</option></select></label></div><button :disabled="busy||!left||!right" @click="run(compare)">加载两图比较</button><template v-if="comparison"><ImageComparison :left="media(comparison.items[0].reference_id)" :right="media(comparison.items[1].reference_id)" :left-label="comparison.items[0].title" :right-label="comparison.items[1].title"/><div class="table-scroll"><table><thead><tr><th>参数</th><th>左图</th><th>右图</th></tr></thead><tbody><tr v-for="d in comparison.differences" :key="d.field"><td>{{d.field}}</td><td><pre>{{d.left==null?'未记录':JSON.stringify(d.left,null,2)}}</pre></td><td><pre>{{d.right==null?'未记录':JSON.stringify(d.right,null,2)}}</pre></td></tr></tbody></table></div><p v-if="!comparison.differences.length">已记录参数没有差异。缺失参数不代表参数相同。</p><details><summary>全部已记录参数与来源</summary><pre>{{JSON.stringify(comparison.items,null,2)}}</pre></details></template></section>
<section class="card grid"><div class="row"><h2>生成批次</h2><button :disabled="busy" @click="run(load)">刷新批次</button></div><p class="small muted">任务在后台持久保存；离开页面停止轮询，服务不会自动启动。重试需明确重新提交，已生成图片保留。</p><article v-for="b in batches.items" :key="b.id" class="grid"><details><summary>{{b.created_at}} · {{b.recipe.backend}} · #{{b.id}}</summary><pre>{{JSON.stringify(b.recipe,null,2)}}</pre></details><JobProgress :job="b.job"/><p v-if="b.notice">{{b.notice}}</p><button :disabled="busy||['queued','running'].includes(b.job?.status)" @click="retry(b)">载入配方（再次点击生成才执行）</button></article><p v-if="!batches.total" class="empty">还没有生成批次；可以直接管理手动图片。</p><nav class="row"><button :disabled="busy||!offset" @click="offset-=20;run(load)">上一页批次</button><span>{{batches.total}}批</span><button :disabled="busy||offset+20>=batches.total" @click="offset+=20;run(load)">下一页批次</button></nav></section>
</div></template>
<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto;font-size:12px}.table-scroll{overflow:auto;max-width:100%}h2{margin:0}input[type=checkbox]{width:auto}td{max-width:260px}.field{min-width:0}</style>
